196	    /**
197	     * The owner's preferred contact channel, derived on read: {@code 'EMAIL'} when an
198	     * email address is present, otherwise {@code 'PHONE'}.
199	     *
200	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
201	     */
202	    @Transient
203	    public String getContactPreference() {
204	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
205	    }
