292	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
293	        List<String> errors = new ArrayList<>();
294	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
295	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
296	        requireText("address", ownerFieldsDto.getAddress(), errors);
297	        requireText("city", ownerFieldsDto.getCity(), errors);
298	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
299	        if (!errors.isEmpty()) {
300	            throw new RequiredFieldsMissingException(errors);
301	        }
302	    }
