366	    /**
367	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
368	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
369	     * and country code are present they are kept; otherwise country code {@code '+61'} is
370	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
371	     * must contain 8 to 15 digits after the {@code '+'}, and for the recognised country codes
372	     * the national-number length must match the country: {@code '+61'} (Australia) requires
373	     * exactly 9 national digits and {@code '+1'} (NANP) requires exactly 10.
374	     *
375	     * @param raw the submitted telephone, possibly {@code null}
376	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
377	     */
378	    private static String toE164(String raw) {
379	        if (raw == null) {
380	            return null;
381	        }
382	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
383	        String digits;
384	        if (cleaned.startsWith("+")) {
385	            digits = cleaned.substring(1);
386	        } else {
387	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
388	            digits = "61" + national;
389	        }
390	        if (!digits.matches("[0-9]{8,15}")) {
391	            return null;
392	        }
393	        if (digits.startsWith("61")) {
394	            // Australia: exactly 9 national digits after the '+61' country code.
395	            if (digits.length() - 2 != 9) {
396	                return null;
397	            }
398	        } else if (digits.startsWith("1")) {
399	            // NANP: exactly 10 national digits after the '+1' country code.
400	            if (digits.length() - 1 != 10) {
401	                return null;
402	            }
403	        }
404	        return "+" + digits;
405	    }
