407	    /**
408	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
409	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
410	     * each stored owner's telephone is normalized the same way before comparison so differing
411	     * input formats collapse to the same value.
412	     *
413	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
414	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
415	     *                                     same E.164 telephone
416	     */
417	    /**
418	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
419	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
420	     * the parts may contain whitespace or a second {@code @}.
421	     */
422	    private static final Pattern EMAIL_PATTERN =
423	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
424	
425	    /**
426	     * Normalizes the submitted email when present: the value is trimmed, required to be a
427	     * syntactically valid address, and written back lower-cased so it is persisted and echoed
428	     * back in canonical form. A {@code null} email is left untouched — the field is optional.
429	     *
430	     * @param ownerFieldsDto the submitted owner fields
431	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically valid
432	     */
433	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
434	        String email = ownerFieldsDto.getEmail();
435	        if (email == null) {
436	            return;
437	        }
438	        String trimmed = email.strip();
439	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
440	            throw new InvalidEmailException(email);
441	        }
442	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
443	    }
