608	    /**
609	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
610	     *
611	     * @param value the string to hash
612	     * @return the 64-character lower-case hex digest
613	     */
614	    private static String sha256Hex(String value) {
615	        try {
616	            byte[] digest = MessageDigest.getInstance("SHA-256")
617	                .digest(value.getBytes(StandardCharsets.UTF_8));
618	            StringBuilder sb = new StringBuilder(digest.length * 2);
619	            for (byte b : digest) {
620	                sb.append(String.format("%02x", b));
621	            }
622	            return sb.toString();
623	        }
624	        catch (NoSuchAlgorithmException e) {
625	            throw new IllegalStateException("SHA-256 not available", e);
626	        }
627	    }
628	
629	    /**
630	     * Rejects a create whose whole derived {@code identityKey} already equals that of an existing
631	     * owner. This single key consolidates what used to be three separate duplicate checks
632	     * (telephone, email and household): the key is
633	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} (see
634	     * {@link #identityKeyFor}), and a create is a duplicate only when its <em>whole</em> key
635	     * matches an existing owner's. Because the telephone is part of the key, two members of the
636	     * same household (same {@code householdId}) with different telephones have different identity
637	     * keys and are both allowed; only an exact full-key match is rejected. The submitted telephone
638	     * and email have already been normalized by {@link #normalizeTelephone} and
639	     * {@link #normalizeEmail}, and each existing owner's key is computed the same way so differing
640	     * input formats collapse to the same value.
641	     *
642	     * @param ownerFieldsDto the submitted owner fields (telephone and email already normalized)
643	     * @throws DuplicateIdentityException with a 409 status if another owner already has the same
644	     *                                    whole identity key
645	     */
646	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
647	        String identityKey = identityKeyFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress(),
648	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail());
649	        boolean duplicate = this.clinicService.findAllOwners().stream()
650	            .map(owner -> identityKeyFor(owner.getLastName(), owner.getAddress(),
651	                owner.getTelephone(), owner.getEmail()))
652	            .anyMatch(identityKey::equals);
653	        if (duplicate) {
654	            throw new DuplicateIdentityException(identityKey);
655	        }
656	    }
657	
658	    /**
659	     * Computes an owner's derived {@code identityKey} from its identity-bearing fields:
660	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. The telephone is
661	     * normalized to E.164 form (see {@link #toE164}), the email is lower-cased (empty when
662	     * absent), and the {@code householdId} is derived from the collapsed {@code lastName} and
663	     * {@code address} the same way {@link #assignHouseholdId} assigns it (see
664	     * {@link #householdIdFor}). Deriving every part canonically means two owners collide only when
665	     * their whole identities match, regardless of the exact input formats.
666	     *
667	     * @param lastName  the owner's last name
668	     * @param address   the owner's address
669	     * @param telephone the owner's telephone, in any format {@link #toE164} accepts
670	     * @param email     the owner's email, possibly {@code null}
671	     * @return the canonical identity key
672	     */
673	    private static String identityKeyFor(String lastName, String address, String telephone, String email) {
674	        String normalizedTelephone = toE164(telephone);
675	        String telephonePart = normalizedTelephone == null ? "" : normalizedTelephone;
676	        String emailPart = email == null ? "" : email.strip().toLowerCase(Locale.ROOT);
677	        return telephonePart + "|" + emailPart + "|" + householdIdFor(lastName, address);
678	    }
679	
680	    /**
681	     * The maximum number of owners permitted in a single city. A create is rejected once the
682	     * owner's city already contains this many owners.
683	     */
684	    private static final long CITY_CAPACITY = 50;
685	
686	    /**
687	     * Rejects a create whose {@code city} already contains {@link #CITY_CAPACITY} or more owners,
688	     * compared case-insensitively (matching {@link #assignCustomerCode}). The count is taken
689	     * before this owner is persisted.
690	     *
691	     * @param city the submitted city
692	     * @throws CityAtCapacityException with a 409 status if the city is already at capacity
693	     */
694	    private void rejectCityAtCapacity(String city) {
695	        long count = this.clinicService.findAllOwners().stream()
696	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
697	            .count();
698	        if (count >= CITY_CAPACITY) {
699	            throw new CityAtCapacityException(city);
700	        }
701	    }
702	
703	    /**
704	     * The maximum number of owners permitted to be created in a single day. A create is
705	     * rejected once this many owners already carry today's {@code registrationDate}.
706	     */
707	    private static final long DAILY_LIMIT = 100;
708	
709	    /**
710	     * Rejects a create once {@link #DAILY_LIMIT} or more owners already carry the given adjusted
711	     * business day as their {@code registrationDate}. The day counted against is this create's
712	     * effective registration date after the business-day roll (see {@link #defaultRegistrationDate}),
713	     * so owners are counted per adjusted business day. The count is taken before this owner is
714	     * persisted.
715	     *
716	     * @param businessDay the effective, business-day-adjusted registration date of this create
717	     * @throws DailyOwnerLimitExceededException with a 429 status if the day is already at the limit
718	     */
719	    private void rejectDailyLimit(LocalDate businessDay) {
720	        long count = this.clinicService.findAllOwners().stream()
721	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
722	            .count();
723	        if (count >= DAILY_LIMIT) {
724	            throw new DailyOwnerLimitExceededException(businessDay);
725	        }
726	    }
727	
728	    /**
729	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
730	     * every internal run of whitespace is collapsed to a single space, and the result is
731	     * lower-cased. A {@code null} value collapses to the empty string.
732	     *
733	     * @param value the value to canonicalize, possibly {@code null}
734	     * @return the collapsed, lower-cased value
735	     */
736	    private static String collapse(String value) {
737	        if (value == null) {
738	            return "";
739	        }
740	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
741	    }
742	
743	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
744	    @Override
745	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
746	        Owner owner = this.clinicService.findOwnerById(ownerId);
747	        if (owner != null) {
748	            Pet pet = owner.getPet(petId);
749	            if (pet != null) {
750	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
751	            }
752	        }
753	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
754	    }
755	}
